// Enhanced User Profile Management
export async function upsertUserProfile(profile: Partial<UserProfile>) {
  try {
    const { data, error } = await supabase
      .from('profiles')
      .upsert({
        ...profile,
        updated_at: new Date().toISOString()
      })
      .select()
      .single()

    if (error) throw error
    return data
  } catch (error) {
    console.error('Error upserting user profile:', error)
    throw error
  }
}

export async function updateUserLoyalty(userId: string, pointsEarned: number, orderAmount: number) {
  try {
    const { data: currentProfile, error: fetchError } = await supabase
      .from('profiles')
      .select('loyalty_points, loyalty_tier, total_orders, total_spent')
      .eq('user_id', userId)
      .single()

    if (fetchError) throw fetchError

    const newPoints = (currentProfile.loyalty_points || 0) + pointsEarned
    const newTotalOrders = (currentProfile.total_orders || 0) + 1
    const newTotalSpent = (currentProfile.total_spent || 0) + orderAmount
    
    // Calculate new tier based on total spent
    let newTier = currentProfile.loyalty_tier || 'bronze'
    if (newTotalSpent >= 50000) newTier = 'platinum'
    else if (newTotalSpent >= 20000) newTier = 'gold'
    else if (newTotalSpent >= 5000) newTier = 'silver'

    const { data, error } = await supabase
      .from('profiles')
      .update({
        loyalty_points: newPoints,
        loyalty_tier: newTier,
        total_orders: newTotalOrders,
        total_spent: newTotalSpent,
        updated_at: new Date().toISOString()
      })
      .eq('user_id', userId)
      .select()
      .single()

    if (error) throw error
    return data
  } catch (error) {
    console.error('Error updating user loyalty:', error)
    throw error
  }
}

// Enhanced Order Management
export async function createEnterpriseOrder(order: Omit<Order, 'id' | 'order_number' | 'created_at' | 'updated_at'>) {
  try {
    // Generate order number
    const { data: orderNumberData, error: orderNumberError } = await supabase
      .rpc('generate_order_number')
    
    if (orderNumberError) throw orderNumberError

    // Calculate loyalty points
    const { data: profile, error: profileError } = await supabase
      .from('profiles')
      .select('loyalty_tier')
      .eq('user_id', order.user_id)
      .single()

    if (profileError) throw profileError

    const loyaltyPoints = await supabase
      .rpc('calculate_loyalty_points', {
        order_amount: order.total_amount,
        customer_tier: profile?.loyalty_tier || 'bronze'
      })

    // Create order with generated number and loyalty points
    const { data, error } = await supabase
      .from('orders')
      .insert([{
        ...order,
        order_number: orderNumberData,
        loyalty_points_earned: loyaltyPoints,
        estimated_delivery_time: new Date(Date.now() + (order.preparation_time_minutes || 20) * 60000).toISOString()
      }])
      .select()
      .single()

    if (error) throw error

    // Update user loyalty points and stats
    await updateUserLoyalty(order.user_id, loyaltyPoints, order.total_amount)

    // Track analytics event
    await trackAnalyticsEvent('order_created', {
      order_id: data.id,
      order_number: data.order_number,
      total_amount: order.total_amount,
      branch_id: order.branch_id,
      payment_method: order.payment_method
    }, order.user_id)

    return data
  } catch (error) {
    console.error('Error creating enterprise order:', error)
    throw error
  }
}

export async function getOrdersByUserId(userId: string, filters?: { status?: string; limit?: number }) {
  try {
    let query = supabase
      .from('orders')
      .select('*')
      .eq('user_id', userId)
      .order('created_at', { ascending: false })

    if (filters?.status) {
      query = query.eq('status', filters.status)
    }
    if (filters?.limit) {
      query = query.limit(filters.limit)
    }

    const { data, error } = await query
    if (error) throw error
    return data
  } catch (error) {
    console.error('Error fetching user orders:', error)
    throw error
  }
}

export async function updateOrderStatus(orderId: string, status: Order['status'], riderId?: string) {
  try {
    const updateData: any = {
      status,
      updated_at: new Date().toISOString()
    }

    if (status === 'delivered') {
      updateData.actual_delivery_time = new Date().toISOString()
    }

    if (riderId) {
      updateData.rider_id = riderId
    }

    const { data, error } = await supabase
      .from('orders')
      .update(updateData)
      .eq('id', orderId)
      .select()
      .single()

    if (error) throw error

    // Track order status update
    await trackAnalyticsEvent('order_status_updated', {
      order_id: orderId,
      new_status: status,
      rider_id: riderId
    })

    return data
  } catch (error) {
    console.error('Error updating order status:', error)
    throw error
  }
}

