// Coupon Management
export async function validateCoupon(code: string, orderAmount: number, userId?: string) {
  try {
    const { data: coupon, error } = await supabase
      .from('coupons')
      .select('*')
      .eq('code', code.toUpperCase())
      .eq('is_active', true)
      .single()

    if (error) throw error

    // Check if coupon is still valid
    const now = new Date()
    if (coupon.start_date && new Date(coupon.start_date) > now) {
      throw new Error('Coupon not yet active')
    }
    if (coupon.end_date && new Date(coupon.end_date) < now) {
      throw new Error('Coupon expired')
    }

    // Check minimum order amount
    if (coupon.minimum_order_amount && orderAmount < coupon.minimum_order_amount) {
      throw new Error(`Minimum order amount of Rs. ${coupon.minimum_order_amount} required`)
    }

    // Check usage limits
    if (coupon.usage_limit && coupon.usage_count >= coupon.usage_limit) {
      throw new Error('Coupon usage limit reached')
    }

    // Check customer usage limit
    if (userId && coupon.customer_usage_limit) {
      const { data: usageCount, error: usageError } = await supabase
        .from('coupon_usage')
        .select('id')
        .eq('coupon_id', coupon.id)
        .eq('customer_id', userId)
        .count()

      if (usageError) throw usageError
      if (usageCount && usageCount >= coupon.customer_usage_limit) {
        throw new Error('Customer usage limit reached for this coupon')
      }
    }

    return coupon
  } catch (error) {
    console.error('Error validating coupon:', error)
    throw error
  }
}

export async function applyCoupon(couponId: string, orderId: string, discountAmount: number) {
  try {
    // Update coupon usage count
    await supabase
      .from('coupons')
      .update({ usage_count: supabase.raw('usage_count + 1') })
      .eq('id', couponId)

    // Track coupon usage
    const { data, error } = await supabase
      .from('coupon_usage')
      .insert([{
        coupon_id: couponId,
        order_id: orderId,
        discount_amount: discountAmount,
        used_at: new Date().toISOString()
      }])
      .select()
      .single()

    if (error) throw error
    return data
  } catch (error) {
    console.error('Error applying coupon:', error)
    throw error
  }
}

// Rider Management
export async function getAvailableRiders(branchId?: string) {
  try {
    let query = supabase
      .from('riders')
      .select('*')
      .eq('is_available', true)

    if (branchId) {
      query = query.eq('branch_id', branchId)
    }

    const { data, error } = await query.order('rating DESC, total_deliveries DESC')
    if (error) throw error
    return data
  } catch (error) {
    console.error('Error fetching available riders:', error)
    throw error
  }
}

export async function assignRider(orderId: string, riderId: string) {
  try {
    // Mark rider as unavailable
    await supabase
      .from('riders')
      .update({ is_available: false })
      .eq('id', riderId)

    // Assign rider to order
    const { data, error } = await supabase
      .from('orders')
      .update({
        rider_id: riderId,
        status: 'out_for_delivery',
        updated_at: new Date().toISOString()
      })
      .eq('id', orderId)
      .select()
      .single()

    if (error) throw error
    return data
  } catch (error) {
    console.error('Error assigning rider:', error)
    throw error
  }
}

// Analytics Tracking
export async function trackAnalyticsEvent(eventType: string, properties: any, userId?: string) {
  try {
    const { data, error } = await supabase
      .from('analytics_events')
      .insert([{
        event_type: eventType,
        user_id: userId,
        properties,
        timestamp: new Date().toISOString()
      }])
      .select()
      .single()

    if (error) throw error
    return data
  } catch (error) {
    console.error('Error tracking analytics event:', error)
    // Don't throw error for analytics to avoid breaking main flow
  }
}

